"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[2452],{21896:(e,n,t)=>{t.r(n),t.d(n,{assets:()=>l,contentTitle:()=>a,default:()=>c,frontMatter:()=>i,metadata:()=>s,toc:()=>h});var o=t(74848),r=t(28453);const i={slug:"3 Years of DefconQ - And We Are Just Getting Started",title:"3 Years of DefconQ - And We Are Just Getting Started",authors:["alexander"],hide_table_of_contents:!0,tags:["kdb/q","Happy Birthday","DefconQ","Just Getting Started"]},a=void 0,s={permalink:"/blog/3 Years of DefconQ - And We Are Just Getting Started",source:"@site/blog/2026-09-04-3-years-Defconq/index.mdx",title:"3 Years of DefconQ - And We Are Just Getting Started",description:"Three years.",date:"2026-09-04T00:00:00.000Z",tags:[{label:"kdb/q",permalink:"/blog/tags/kdb-q"},{label:"Happy Birthday",permalink:"/blog/tags/happy-birthday"},{label:"DefconQ",permalink:"/blog/tags/defcon-q"},{label:"Just Getting Started",permalink:"/blog/tags/just-getting-started"}],readingTime:10.09,hasTruncateMarker:!0,authors:[{name:"Alexander Unterrainer",title:"DefconQ, KDB/Q Developer, Consultant",url:"https://github.com/AUnterrainer",imageURL:"/img/alex.jpeg",key:"alexander"}],frontMatter:{slug:"3 Years of DefconQ - And We Are Just Getting Started",title:"3 Years of DefconQ - And We Are Just Getting Started",authors:["alexander"],hide_table_of_contents:!0,tags:["kdb/q","Happy Birthday","DefconQ","Just Getting Started"]},unlisted:!1,nextItem:{title:"DefconQ Happy Hour Is Back!",permalink:"/blog/DefconQ Happy Hour Is Back!"}},l={authorsImageUrls:[void 0]},h=[{value:"From DefconQ to Wall Street \ud83d\uddfd",id:"from-defconq-to-wall-street-",level:2},{value:"Meeting Some of My q Heroes",id:"meeting-some-of-my-q-heroes",level:2},{value:"From Attendee to Advisory Board",id:"from-attendee-to-advisory-board",level:2},{value:"Happy Hours, Discord and Building a Real Community",id:"happy-hours-discord-and-building-a-real-community",level:2},{value:"DefconQ Meets the Wider Quant World",id:"defconq-meets-the-wider-quant-world",level:2},{value:"DefconQ Goes Academic",id:"defconq-goes-academic",level:2},{value:"And, Of Course... Content",id:"and-of-course-content",level:2},{value:"DefconQ Mentorship",id:"defconq-mentorship",level:2},{value:"Next Stop: Iverson College",id:"next-stop-iverson-college",level:2},{value:"But My Biggest Milestone Had Nothing to Do With q",id:"but-my-biggest-milestone-had-nothing-to-do-with-q",level:2},{value:"So... What&#39;s Next?",id:"so-whats-next",level:2},{value:"Thank You",id:"thank-you",level:2}];function d(e){const n={a:"a",em:"em",h2:"h2",img:"img",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.p,{children:"Three years."}),"\n",(0,o.jsx)(n.p,{children:"It somehow became a DefconQ tradition to mark every birthday with a blog post: a chance to look back at the previous twelve months, reflect on what happened, celebrate some of the milestones, and, inevitably, talk about what comes next."}),"\n",(0,o.jsx)(n.p,{children:"And as I sit down to write the third edition, I genuinely couldn't be happier with how the past year has unfolded."}),"\n",(0,o.jsx)(n.p,{children:"When I started DefconQ three years ago, the idea was pretty simple: make q more accessible, document some of the knowledge I'd accumulated over the years, improve my own understanding along the way, and hopefully give something back to a technology and community that have played a huge part in my career."}),"\n",(0,o.jsx)(n.p,{children:"Three years later, DefconQ has become much more than a technical blog."}),"\n",(0,o.jsx)(n.p,{children:"It's become a community."}),"\n",(0,o.jsx)(n.p,{children:"And this year, more than any other, felt like the year that community really started coming together. The DefconQ blog itself now spans dozens of articles across KDB/Q, architecture, market data and community topics, while the Discord Server, events and collaborations have increasingly expanded DefconQ beyond written content."}),"\n",(0,o.jsx)(n.p,{children:"So, in keeping with tradition, let's rewind twelve months."}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.img,{alt:"3 Years DefconQ - Happy Birtday",src:t(63410).A+"",width:"1370",height:"1148"})}),"\n",(0,o.jsx)(n.h2,{id:"from-defconq-to-wall-street-",children:"From DefconQ to Wall Street \ud83d\uddfd"}),"\n",(0,o.jsxs)(n.p,{children:["The third year started with a pretty big milestone for me personally: ",(0,o.jsx)(n.strong,{children:"my first trip to New York."})]}),"\n",(0,o.jsxs)(n.p,{children:["And if you're going to visit New York for the first time as someone who has spent most of his career working in finance, there are probably worse ways to do it than spending a week working on ",(0,o.jsx)(n.strong,{children:"Wall Street."})]}),"\n",(0,o.jsxs)(n.p,{children:["During the same trip, I had the opportunity to take part in the ",(0,o.jsx)(n.a,{href:"https://www.rebellionresearch.com/cornell-financial-engineering-manhattan-2025-future-of-finance-ai-conference",children:(0,o.jsx)(n.strong,{children:"Cornell Financial Engineering Manhattan 2025 Future of Finance & AI Conference"})}),", joining a panel right in the heart of New York's financial district."]}),"\n",(0,o.jsx)(n.p,{children:"For someone who has been fascinated by finance, technology and quantitative finance for most of his adult life, that was a pretty special moment."}),"\n",(0,o.jsxs)(n.p,{children:["But DefconQ trips are rarely just about conferences. We also brought the ",(0,o.jsx)(n.strong,{children:"DefconQ Happy Hour to New York"}),", giving me the opportunity to meet plenty of people from the US KDB/Q and quant community whom I'd previously only known through LinkedIn, email or the blog. It was one of two anniversary Happy Hours that September, alongside Belfast."]}),"\n",(0,o.jsx)(n.p,{children:"There is something quite surreal about starting a niche technical blog from your laptop and, two years later, standing in a bar on the other side of the Atlantic surrounded by people who know that blog.\nThose are the moments that remind me why I keep doing this."}),"\n",(0,o.jsx)(n.h2,{id:"meeting-some-of-my-q-heroes",children:"Meeting Some of My q Heroes"}),"\n",(0,o.jsxs)(n.p,{children:["New York also delivered another personal highlight. I finally got to meet ",(0,o.jsx)(n.strong,{children:"Nick Psaris"})," my favourite q author and someone whose work I've admired for years."]}),"\n",(0,o.jsx)(n.p,{children:"Anyone who has spent serious time learning q will know how valuable a good technical author can be. The best books don't simply teach syntax; they change the way you think about a language. Nick's work has done exactly that for me, so getting the chance to meet him in person was genuinely special."}),"\n",(0,o.jsx)(n.p,{children:"And then there was another encounter that needs very little introduction."}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"Arthur Whitney"})}),"\n",(0,o.jsx)(n.p,{children:"Meeting the man behind k, and one of the people whose ideas ultimately shaped an enormous part of my professional life, was certainly one for the DefconQ history books. Not bad for a first trip to New York."}),"\n",(0,o.jsx)(n.h2,{id:"from-attendee-to-advisory-board",children:"From Attendee to Advisory Board"}),"\n",(0,o.jsxs)(n.p,{children:["Another big development this year came through my involvement with ",(0,o.jsx)(n.a,{href:"https://www.alphaevents.com/events-futurealphaglobal",children:(0,o.jsx)(n.strong,{children:"Future Alpha / Quant Strats"})}),"."]}),"\n",(0,o.jsxs)(n.p,{children:["What started with attending the conference because of my own fascination with quantitative finance has grown into a much deeper relationship. I joined the advisory board and, at Quant Strats Europe, ran a hands-on KDB/Q masterclass.\nThe session, ",(0,o.jsx)(n.strong,{children:'"Data to Deployment: End-to-End Coding for Quant Analysts,"'})," took attendees through the journey from ingesting data all the way to signal generation, optimisation, deployment and visualisation, a practical look at how the individual pieces of a quantitative system actually fit together."]}),"\n",(0,o.jsxs)(n.p,{children:["That was exactly the kind of session I wanted DefconQ to be associated with from the beginning:\n",(0,o.jsx)(n.strong,{children:"Less"}),": ",(0,o.jsx)(n.em,{children:"here are 100 slides about what you could theoretically do."})]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"More"}),": ",(0,o.jsx)(n.em,{children:"open the laptop and let's actually build the thing."})]}),"\n",(0,o.jsxs)(n.p,{children:["And apparently they haven't managed to get rid of me yet: ",(0,o.jsx)(n.strong,{children:"I'll be returning to New York for Future Alpha 2027."})]}),"\n",(0,o.jsx)(n.h2,{id:"happy-hours-discord-and-building-a-real-community",children:"Happy Hours, Discord and Building a Real Community"}),"\n",(0,o.jsx)(n.p,{children:"The Happy Hours continued too."}),"\n",(0,o.jsx)(n.p,{children:"What started as an experiment has become one of my favourite parts of DefconQ. Getting developers, quants, architects, students and industry veterans into the same room, with no sales pitch and no complicated agenda, has repeatedly produced some of the best conversations I've had around KDB/Q."}),"\n",(0,o.jsxs)(n.p,{children:["This year also saw the launch of the ",(0,o.jsx)(n.strong,{children:"DefconQ Community Discord Server."})]}),"\n",(0,o.jsx)(n.p,{children:"That felt like an important next step."}),"\n",(0,o.jsx)(n.p,{children:"A blog is inherently one-directional: I write something, you read it."}),"\n",(0,o.jsx)(n.p,{children:"A community should be different."}),"\n",(0,o.jsxs)(n.p,{children:["The Discord gives people somewhere to ask questions, discuss ideas, share projects, tackle the Weekly Q Challenges and, most importantly, talk to each other. It turned DefconQ from somewhere you ",(0,o.jsx)(n.em,{children:"visit"})," into somewhere the community can actually ",(0,o.jsx)(n.em,{children:"meet"}),"."]}),"\n",(0,o.jsx)(n.p,{children:"And that's something I'd like to build on much further over the coming year."}),"\n",(0,o.jsx)(n.h2,{id:"defconq-meets-the-wider-quant-world",children:"DefconQ Meets the Wider Quant World"}),"\n",(0,o.jsxs)(n.p,{children:["Another theme of the past year has been collaboration. DefconQ teamed up with ",(0,o.jsx)(n.strong,{children:"Databento"}),", bringing the worlds of KDB/Q and modern market data infrastructure closer together. The collaboration grew naturally from the same problem I've written about many times: there is no serious KDB/Q system without data flowing through it. Together with ",(0,o.jsx)(n.strong,{children:"Databento and CoinDesk,"})," we also brought the wider quant and data community together for ",(0,o.jsx)(n.strong,{children:"Quant Night in London."})]}),"\n",(0,o.jsx)(n.p,{children:"That's something I'd like DefconQ to continue doing."}),"\n",(0,o.jsx)(n.p,{children:"KDB/Q doesn't exist in isolation."}),"\n",(0,o.jsx)(n.p,{children:"It sits at the intersection of quantitative finance, market data, trading infrastructure, databases and increasingly AI. Connecting our relatively small but highly specialised community with the wider financial technology ecosystem creates opportunities for everyone."}),"\n",(0,o.jsx)(n.h2,{id:"defconq-goes-academic",children:"DefconQ Goes Academic"}),"\n",(0,o.jsxs)(n.p,{children:["There was another milestone I certainly wasn't expecting when I started writing three years ago. ",(0,o.jsx)(n.strong,{children:"DefconQ was referenced in an academic paper."})," Professor ",(0,o.jsx)(n.strong,{children:"Alexander Bilokon"})," included DefconQ in his work discussing the history and evolution of trading, mathematical finance and the quant profession."]}),"\n",(0,o.jsx)(n.p,{children:"For someone who started DefconQ largely as a personal learning project, seeing the platform referenced in academic work about an industry I've spent my career in was a rather nice full-circle moment.\nTurns out all those evenings spent writing about q instead of watching Netflix weren't entirely wasted after all."}),"\n",(0,o.jsx)(n.h2,{id:"and-of-course-content",children:"And, Of Course... Content"}),"\n",(0,o.jsx)(n.p,{children:"Despite everything else going on, DefconQ remained what it has always been at its core:"}),"\n",(0,o.jsx)(n.p,{children:"A place to learn."}),"\n",(0,o.jsx)(n.p,{children:"More blog posts."}),"\n",(0,o.jsx)(n.p,{children:"More tutorials."}),"\n",(0,o.jsx)(n.p,{children:"More newsletters."}),"\n",(0,o.jsx)(n.p,{children:"More architecture discussions."}),"\n",(0,o.jsx)(n.p,{children:"More market-data content."}),"\n",(0,o.jsx)(n.p,{children:"More community posts."}),"\n",(0,o.jsx)(n.p,{children:"More Weekly Q Challenges."}),"\n",(0,o.jsx)(n.p,{children:"And occasionally more terrible q-related jokes than anyone reasonably asked for."}),"\n",(0,o.jsx)(n.p,{children:"This year's topics stretched from gateways and real-time architectures to market data, extended trading hours, community projects and the changing k ecosystem."}),"\n",(0,o.jsx)(n.p,{children:"And that last point is particularly interesting."}),"\n",(0,o.jsx)(n.p,{children:"Anyone following my recent posts will have noticed that the ecosystem itself seems to be entering a new chapter. New runtimes and implementations are appearing. New people are building. Old assumptions are being challenged."}),"\n",(0,o.jsx)(n.p,{children:"There is a lot happening."}),"\n",(0,o.jsx)(n.p,{children:"And DefconQ intends to be right in the middle of it."}),"\n",(0,o.jsx)(n.h2,{id:"defconq-mentorship",children:"DefconQ Mentorship"}),"\n",(0,o.jsxs)(n.p,{children:["This year I also launched something I'd been thinking about for quite some time: the ",(0,o.jsx)(n.strong,{children:"DefconQ Mentorship Program."})]}),"\n",(0,o.jsx)(n.p,{children:"The idea was to offer something more personal than another tutorial, to work directly with developers who want to accelerate their KDB/Q journey, whether that's improving their technical skills, understanding architecture, preparing for interviews or navigating the industry."}),"\n",(0,o.jsx)(n.p,{children:"I wasn't entirely sure what the response would be."}),"\n",(0,o.jsx)(n.p,{children:"Then it reached full capacity."}),"\n",(0,o.jsx)(n.p,{children:"That genuinely surprised me."}),"\n",(0,o.jsx)(n.p,{children:"But it also reinforced something I've increasingly realised through DefconQ: there is still significant demand for structured, practical KDB/Q education, particularly the kind that bridges the enormous gap between knowing q syntax and actually being able to build and operate real systems."}),"\n",(0,o.jsx)(n.p,{children:"There is plenty more I want to do here."}),"\n",(0,o.jsx)(n.h2,{id:"next-stop-iverson-college",children:"Next Stop: Iverson College"}),"\n",(0,o.jsx)(n.p,{children:"And the third year isn't quite finished yet."}),"\n",(0,o.jsxs)(n.p,{children:["In just a couple of days, I'm heading to ",(0,o.jsx)(n.strong,{children:"Suffolk"}),", where DefconQ will co-host this year's ",(0,o.jsx)(n.strong,{children:"Iverson College"})," alongside ",(0,o.jsx)(n.strong,{children:"Stephen Taylor."})]}),"\n",(0,o.jsx)(n.p,{children:"Iverson College has a long history within the array-programming world and was founded in honour of Kenneth E. Iverson, the creator of APL and the intellectual ancestor of much of what eventually became k and q. This year's gathering returns to Milden Hall, with DefconQ joining Stephen in bringing the community together."}),"\n",(0,o.jsx)(n.p,{children:"But for me, this isn't simply another event."}),"\n",(0,o.jsx)(n.p,{children:"I hope it becomes an opportunity to bring together some of the people who care deeply about the future of q, k and array programming and start laying foundations for what comes next."}),"\n",(0,o.jsxs)(n.p,{children:["We've been calling it ",(0,o.jsx)(n.strong,{children:"QKommunity"}),"."]}),"\n",(0,o.jsx)(n.p,{children:"More on that very soon."}),"\n",(0,o.jsx)(n.h2,{id:"but-my-biggest-milestone-had-nothing-to-do-with-q",children:"But My Biggest Milestone Had Nothing to Do With q"}),"\n",(0,o.jsx)(n.p,{children:"For all the conferences, Happy Hours, workshops, blog posts, collaborations and DefconQ milestones, the biggest event of my year had absolutely nothing to do with technology."}),"\n",(0,o.jsxs)(n.p,{children:["In April, my wife and I welcomed our first son, ",(0,o.jsx)(n.strong,{children:"Leo"}),"."]}),"\n",(0,o.jsx)(n.p,{children:"Becoming a parent for the first time is difficult to put into words. You can spend years chasing professional milestones, another client, another conference, another project, another achievement, and then one tiny human arrives and rather efficiently rearranges your entire definition of what matters."}),"\n",(0,o.jsx)(n.p,{children:"It has undoubtedly been the most life-changing and beautiful part of the past twelve months."}),"\n",(0,o.jsxs)(n.p,{children:["It has also introduced me to an exciting new distributed-systems problem called ",(0,o.jsx)(n.strong,{children:"sleep deprivation"}),", for which I have yet to find a sufficiently scalable architecture."]}),"\n",(0,o.jsx)(n.p,{children:"I'm working on it."}),"\n",(0,o.jsx)(n.h2,{id:"so-whats-next",children:"So... What's Next?"}),"\n",(0,o.jsx)(n.p,{children:"Those of you who follow DefconQ closely may have noticed that the pace of new content has slowed slightly at times."}),"\n",(0,o.jsx)(n.p,{children:"Part of that is simply life getting busier."}),"\n",(0,o.jsx)(n.p,{children:"But that's not the whole story."}),"\n",(0,o.jsx)(n.p,{children:"After three years of writing, DefconQ now contains a significant amount of KDB/Q knowledge. There are tutorials covering fundamentals, architecture, real-time systems, gateways, market data, q concepts and much more. At some point, publishing another article simply for the sake of maintaining a posting schedule doesn't add much value."}),"\n",(0,o.jsxs)(n.p,{children:["I'd rather publish something because ",(0,o.jsx)(n.strong,{children:"it's worth reading."})]}),"\n",(0,o.jsx)(n.p,{children:"And increasingly, my attention is moving towards bigger projects."}),"\n",(0,o.jsx)(n.p,{children:"There is a lot happening behind the scenes."}),"\n",(0,o.jsx)(n.p,{children:"Some of it builds on the content already available through DefconQ. Some of it expands into education. Some of it is about community. And some of it is connected to the changes currently taking place across the wider k and q ecosystem.\nI won't spoil those announcements here."}),"\n",(0,o.jsxs)(n.p,{children:["But trust me: ",(0,o.jsx)(n.strong,{children:"DefconQ slowing down does not mean DefconQ is slowing down."})]}),"\n",(0,o.jsx)(n.p,{children:"Quite the opposite."}),"\n",(0,o.jsx)(n.p,{children:"There is much more planned, and I've been working tirelessly in the background to turn some of those ideas into reality."}),"\n",(0,o.jsx)(n.p,{children:"Three years in, I still feel like we're only getting started."}),"\n",(0,o.jsx)(n.h2,{id:"thank-you",children:"Thank You"}),"\n",(0,o.jsxs)(n.p,{children:["Last but certainly not least, I want to thank ",(0,o.jsx)(n.strong,{children:"every single person who has supported DefconQ over the past three years."})]}),"\n",(0,o.jsx)(n.p,{children:"Every time you read one of my articles."}),"\n",(0,o.jsx)(n.p,{children:"Every LinkedIn like."}),"\n",(0,o.jsx)(n.p,{children:"Every comment."}),"\n",(0,o.jsx)(n.p,{children:"Every repost."}),"\n",(0,o.jsx)(n.p,{children:"Every recommendation."}),"\n",(0,o.jsx)(n.p,{children:"Every newsletter subscription."}),"\n",(0,o.jsx)(n.p,{children:"Every person who turns up to a Happy Hour."}),"\n",(0,o.jsx)(n.p,{children:"Every Discord message."}),"\n",(0,o.jsx)(n.p,{children:"Every private message telling me that a tutorial helped you solve a problem, understand a concept, prepare for an interview or learn something new."}),"\n",(0,o.jsx)(n.p,{children:"Those things matter."}),"\n",(0,o.jsx)(n.p,{children:"DefconQ is something I build in my spare time because I genuinely enjoy doing it. Seeing people use it, recommend it and contribute to the community is what gives me the motivation to keep going."}),"\n",(0,o.jsx)(n.p,{children:"So whether you've been following since the first blog post or discovered DefconQ yesterday:"}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"Thank you."})}),"\n",(0,o.jsx)(n.p,{children:"Here's to three years of learning, coding, meeting brilliant people, occasionally arguing about q syntax, and building something I never expected would grow this far."}),"\n",(0,o.jsx)(n.p,{children:"And here's to whatever comes next."}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Happy 3rd Birthday, DefconQ."})," \ud83c\udf82"]}),"\n",(0,o.jsx)(n.p,{children:"We are just getting started."}),"\n",(0,o.jsx)(n.p,{children:"And, as always..."}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Happy Coding!"})," \ud83d\ude80"]})]})}function c(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},63410:(e,n,t)=>{t.d(n,{A:()=>o});const o=t.p+"assets/images/3years-0b427338d43c27674ddf571eaa4e5885.png"},28453:(e,n,t)=>{t.d(n,{R:()=>a,x:()=>s});var o=t(96540);const r={},i=o.createContext(r);function a(e){const n=o.useContext(i);return o.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:a(e.components),o.createElement(i.Provider,{value:n},e.children)}}}]);